content.query:
let ops = AppEvents
    | where TimeGenerated > ago(7d)
    | where Name == "ops_recommendation"
    | extend d = parse_json(Properties)
    | extend run_ts = todatetime(tostring(d.generated_at));
let latest_ops_run = toscalar(ops | summarize max(run_ts));
let latest_ops = ops | where run_ts == latest_ops_run;
//
let latest_cost_snapshot =
    AppEvents
    | where Name == "azure_cost_snapshot"
    | extend cd = parse_json(Properties)
    | summarize arg_max(TimeGenerated, budget_pct = todouble(cd.budget_percent_used), dod_pct = todouble(cd.day_over_day_change_pct));
let cost_budget_pct = toscalar(latest_cost_snapshot | project budget_pct);
let cost_dod_pct = toscalar(latest_cost_snapshot | project dod_pct);
//
let cost_row = latest_ops
    | where tostring(d.category) == "cost"
    | extend status_raw = tostring(d.status), worst = tostring(d.worst_severity),
             explanation = tostring(d.explanation), recommendation = tostring(d.recommendation)
    | extend Status = case(status_raw == "worked", "healthy",
                            status_raw == "recommend" and worst == "red", "critical",
                            status_raw == "recommend", "warning",
                            "no data")
    | extend KeyMetric = iff(isnull(cost_budget_pct), "n/a — see Cost + Health", strcat(tostring(round(cost_budget_pct, 1)), "% of budget"))
    | extend Flagged = iff(status_raw != "worked", explanation, "")
    | extend Recommendation = iff(isempty(recommendation), "", recommendation)
    | extend RecentActivity = iff(isnotnull(cost_dod_pct) and abs(cost_dod_pct) > 10,
                                   strcat("Spend ", iff(cost_dod_pct > 0, "up ", "down "), tostring(round(abs(cost_dod_pct), 0)), "% vs. yesterday"), "")
    | project Category = "Cost Control", Status, KeyMetric, Flagged, Recommendation, RecentActivity, GoToDetail = "Cost + Health -> Budget & Forecast";
//
let allowed_reasons = dynamic(["SuccessfulRescale","TriggeredScaleUp","ReplicaUnhealthy","ContainerCrashing","RevisionUpdate"]);
let reason_text = datatable(Reason_s: string, PlainEnglish: string)
[
    "SuccessfulRescale", "scaled up/down",
    "TriggeredScaleUp", "scaled up due to load",
    "ReplicaUnhealthy", "a replica became unhealthy",
    "ContainerCrashing", "a container crashed and restarted",
    "RevisionUpdate", "a new version was deployed"
];
let latest_infra_event =
    ContainerAppSystemLogs_CL
    | where TimeGenerated > ago(7d)
    | where Reason_s in (allowed_reasons)
    | top 1 by TimeGenerated desc
    | lookup kind=leftouter reason_text on Reason_s
    | extend AgeMinutes = round((now() - TimeGenerated) / 1m, 0)
    | extend RelativeTime = iff(AgeMinutes < 60, strcat(tostring(AgeMinutes), "m ago"), strcat(tostring(round(AgeMinutes / 60.0, 1)), "h ago"))
    | extend Sentence = strcat(ContainerAppName_s, " ", PlainEnglish, ", ", RelativeTime)
    | project Sentence;
let infra_activity = toscalar(latest_infra_event | project Sentence);
//
let infra_row = latest_ops
    | where tostring(d.category) == "container_health"
    | extend status_raw = tostring(d.status), worst = tostring(d.worst_severity),
             explanation = tostring(d.explanation), recommendation = tostring(d.recommendation),
             red_count = toint(d.red_count), yellow_count = toint(d.yellow_count)
    | extend Status = case(status_raw == "worked", "healthy",
                            status_raw == "recommend" and worst == "red", "critical",
                            status_raw == "recommend", "warning",
                            "no data")
    | extend KeyMetric = iff(status_raw in ("no_data", "insufficient_data"), "not measured",
                              strcat(tostring(coalesce(red_count, 0) + coalesce(yellow_count, 0)), " app(s) with an issue"))
    | extend Flagged = iff(status_raw != "worked", explanation, "")
    | extend Recommendation = iff(isempty(recommendation), "", recommendation)
    | extend RecentActivity = iff(isnull(infra_activity), "", infra_activity)
    | project Category = "Infrastructure", Status, KeyMetric, Flagged, Recommendation, RecentActivity, GoToDetail = "Cost + Health -> Containers";
//
let api_requests = AppRequests
    | where TimeGenerated > ago(24h)
    | where AppRoleName != "invoice-be-local-f20-verify";
let api_total = toscalar(api_requests | count | project Count);
let api_errors = toscalar(api_requests | where Success == false | count | project Count);
let api_error_pct = iff(api_total > 0, round(100.0 * api_errors / api_total, 2), real(null));
let area_bucket = (T:(TimeGenerated:datetime, Name:string, Success:bool)) {
    T
    | extend Area = case(
        Name has "/invoices" or Name has "/email-ingestion", "Ingestion & Extraction",
        Name has "/chat",                                    "Chat",
        Name has "/audit",                                   "Review & Correction",
        Name has "/autopilot" or Name has "/connectors",     "Autopilot & Connectors",
        Name has "/dashboard",                               "Dashboard & Reporting",
        Name has "/trainer",                                 "Trainer",
        Name has "/billing" or Name has "/admin",            "Billing & Admin",
        Name has "/settings/security" or Name has "/auth",   "Auth",
        "Other")
};
let area_rates = area_bucket(api_requests)
    | summarize Requests = count(), Errors = countif(Success == false) by Area
    | extend ErrorPct = iff(Requests > 0, round(100.0 * Errors / Requests, 2), real(null))
    | order by ErrorPct desc;
let worst_area = toscalar(area_rates | take 1 | project Area);
let worst_area_pct = toscalar(area_rates | take 1 | project ErrorPct);
let hourly_area_rates = area_bucket(api_requests)
    | summarize Requests = count(), Errors = countif(Success == false) by Area, Hour = bin(TimeGenerated, 1h)
    | extend ErrorPct = iff(Requests > 0, round(100.0 * Errors / Requests, 1), real(null))
    | where Requests >= 5
    | order by ErrorPct desc;
let worst_spike_area = toscalar(hourly_area_rates | take 1 | project Area);
let worst_spike_pct = toscalar(hourly_area_rates | take 1 | project ErrorPct);
let worst_spike_time = toscalar(hourly_area_rates | take 1 | project format_datetime(Hour, 'HH:mm'));
//
let api_row = print x = 1
    | extend Status = case(api_total == 0, "no data", api_error_pct >= 5.0, "degraded", "healthy")
    | extend KeyMetric = iff(api_total == 0, "no requests in last 24h",
                              strcat(tostring(api_error_pct), "% error rate -- worst: ", worst_area))
    | extend Flagged = iff(api_error_pct >= 5.0,
                            strcat(worst_area, " is the worst-performing area at ", tostring(worst_area_pct), "% error rate"), "")
    | extend Recommendation = iff(api_error_pct >= 5.0,
                                   strcat("Investigate the ", worst_area, " endpoints -- error rate crossed 5%."), "")
    | extend RecentActivity = iff(isnotnull(worst_spike_pct) and worst_spike_pct >= 5.0,
                                   strcat(worst_spike_area, " error rate spiked to ", tostring(worst_spike_pct), "% at ", worst_spike_time), "")
    | project Category = "API Health", Status, KeyMetric, Flagged, Recommendation, RecentActivity, GoToDetail = "Cost + Health -> By Feature Area";
//
let ai_base = latest_ops
    | where tostring(d.category) == "ai_improvement"
    | extend status_raw = tostring(d.status), worst = tostring(d.worst_severity),
             explanation = tostring(d.explanation), recommendation = tostring(d.recommendation),
             findings_json = tostring(d.findings);
let ai_findings = ai_base
    | project findings_json
    | mv-expand finding = parse_json(findings_json)
    | extend field = tostring(finding.field), value = todouble(finding.value),
             severity = tostring(finding.severity), detail = tostring(finding.detail)
    | extend sev_rank = case(severity == "red", 2, severity == "yellow", 1, 0)
    | order by sev_rank desc;
let ai_pass_rate = toscalar(ai_findings | where field == "pass_rate" | take 1 | project value);
let ai_worst_detail = toscalar(ai_findings | take 1 | project detail);
let ai_row = ai_base
    | extend Status = case(status_raw == "worked", "healthy",
                            status_raw == "recommend" and worst == "red", "critical",
                            status_raw == "recommend", "warning",
                            "no data")
    | extend KeyMetric = iff(isnotnull(ai_pass_rate), strcat(tostring(round(ai_pass_rate * 100, 1)), "% pass rate"), "n/a -- see AI Control Tower Section D")
    | extend Flagged = iff(status_raw != "worked", explanation, "")
    | extend Recommendation = iff(isempty(recommendation), "", recommendation)
    | extend RecentActivity = iff(isnotempty(ai_worst_detail), ai_worst_detail, "")
    | project Category = "AI Health", Status, KeyMetric, Flagged, Recommendation, RecentActivity, GoToDetail = "AI Control Tower -> Nightly Test Quality";
//
union cost_row, infra_row, api_row, ai_row
| extend SortOrder = case(Category == "Cost Control", 1, Category == "Infrastructure", 2, Category == "API Health", 3, 4)
| order by SortOrder asc
| project Category, Status, ["Key metric"] = KeyMetric, ["What's flagged"] = Flagged, Recommendation, ["Recent Activity"] = RecentActivity, ["Go to detail"] = GoToDetail
